function cleanQuestionText(text: string): string {
  if (!text) return '';
  return text.replace(/\s*\([Vv]ariation\s*\d+\)/gi, '').trim();
}

function cleanEngineQuestion(q: ExamQuestion): ExamQuestion {
  if (!q) return q;
  return {
    ...q,
    question_text: cleanQuestionText(q.question_text),
  };
}

export function getAllEngineQuestions(): ExamQuestion[] {
  return [...QUESTION_BANK_DATA, ...DIVERSE_MULTI_TYPE_QUESTIONS].map(cleanEngineQuestion);
}

export function getEngineRandomQuestions(options: {
  count: number;
  topic?: string;
  subtopic?: string;
  course?: string;
  difficulty?: string;
  type?: string;
}): ExamQuestion[] {
  let pool = [...QUESTION_BANK_DATA, ...DIVERSE_MULTI_TYPE_QUESTIONS];

  if (options.course && options.course !== 'all') {
    const allowedTopics = COURSE_TO_TOPICS_MAP[options.course] || [];
    if (allowedTopics.length > 0) {
      pool = pool.filter((q) => q.topic && allowedTopics.includes(q.topic));
    }
  }

  if (options.topic && options.topic !== 'all') {
    const t = options.topic.toLowerCase();
    pool = pool.filter((q) => {
      const qTopic = (q.topic || '').toLowerCase();
      const qSubtopic = (q.subtopic || '').toLowerCase();
      return qTopic === t || qSubtopic === t || qSubtopic.includes(t) ||
        (t.includes('quant') && qSubtopic.includes('quant')) ||
        (t.includes('logic') && qSubtopic.includes('logic')) ||
        (t.includes('verb') && qSubtopic.includes('verb'));
    });
  }

  if (options.subtopic && options.subtopic !== 'all') {
    const st = options.subtopic.toLowerCase();
    pool = pool.filter((q) => {
      const qSubtopic = (q.subtopic || '').toLowerCase();
      return qSubtopic === st || qSubtopic.includes(st) ||
        (st.includes('quant') && qSubtopic.includes('quant')) ||
        (st.includes('logic') && qSubtopic.includes('logic')) ||
        (st.includes('verb') && qSubtopic.includes('verb'));
    });
  }

  if (options.difficulty && options.difficulty !== 'all') {
    pool = pool.filter((q) => q.difficulty === options.difficulty);
  }

  if (options.type && options.type !== 'all') {
    pool = pool.filter((q) => q.type === options.type);
  }

  // Fisher-Yates shuffle
  const copy = [...pool];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }

  return copy.slice(0, Math.min(options.count, copy.length)).map(cleanEngineQuestion);
}
